// Normalize Gate Request - cleans and validates what the caller passed. Never throws: bad input becomes `invalid`.
const src = $input.first().json || {};
const clean = (v) => String(v === undefined || v === null ? '' : v).trim();

const contact_id = clean(src.contact_id);
const channelRaw = clean(src.channel).toLowerCase();
const CHANNEL_MAP = { call: 'Call', sms: 'SMS' };
const channel = CHANNEL_MAP[channelRaw] || '';
const pillar = clean(src.pillar) || 'receptionist';
// attempt is only used by speed-to-lead (quiet-hours exemption); the receptionist never sends it.
const attempt = clean(src.attempt).toLowerCase();
const ATTEMPTS = ['call1', 'call2', 'text', 'call3'];

let invalid = '';
if (!contact_id) invalid = 'missing contact_id';
else if (!/^[A-Za-z0-9]{10,40}$/.test(contact_id)) invalid = 'contact_id is not a valid GHL id';
else if (!channel) invalid = `channel must be "Call" or "SMS", got "${clean(src.channel)}"`;
else if (pillar === 'speedtolead' && !ATTEMPTS.includes(attempt)) invalid = `attempt must be one of ${ATTEMPTS.join('/')} for speedtolead, got "${clean(src.attempt)}"`;

return [{ json: { contact_id, channel, pillar, attempt, invalid } }];

// Decide Gate - Desert Comfort Contact Gate.
// Pure decision logic, reads everything through explicit node references, writes NOTHING itself.
// Fail-closed: anything that can't be evaluated denies and alerts, per the internal contact-state model section 4 item 7.
// Receptionist path (pillar != speedtolead): DND check only, exactly as before.
// Speed-to-lead path adds, in order: stage, human-reached-first tag, active-call lock, quiet hours (2026-10-30).
const req = $('Normalize Gate Request').first().json;
const base = { contact_id: req.contact_id, channel: req.channel, pillar: req.pillar, attempt: req.attempt || '', phone: '', stage: '', allowed: false, deferred: false, delay_until: '', decision: '', reason: '', alert: false, alert_text: '' };

if (req.invalid) {
  return [{ json: { ...base, decision: 'invalid_input', reason: req.invalid, alert: true, alert_text: `Contact Gate got an invalid request: ${req.invalid}.` } }];
}

const cr = $('Get Contact For Gate').first().json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) {
  return [{ json: { ...base, decision: 'fetch_failed', reason: `GET contact returned ${cr.statusCode}`, alert: true,
    alert_text: `Contact Gate could not read contact ${req.contact_id} (HTTP ${cr.statusCode}). Denying ${req.channel} to be safe (fail-closed).` } }];
}

const contact = cr.body.contact;
const phone = contact.phone || '';
const dnd = (contact.dndSettings && contact.dndSettings[req.channel]) || {};
const suppressed = String(dnd.status || '').toLowerCase() === 'active';

// NOTE: opt_in_exception (the internal contact-state model section 6) is deliberately not wired -- nothing sets it yet.

if (suppressed) {
  return [{ json: { ...base, phone, decision: 'denied_dnd', reason: `${req.channel} DND is active on this contact`, allowed: false } }];
}
if (req.pillar !== 'speedtolead') {
  return [{ json: { ...base, phone, decision: 'allowed', reason: `${req.channel} DND is not active`, allowed: true } }];
}

// ---- speed-to-lead checks ----
const readNode = (name) => { try { const n = $(name); return n.isExecuted ? n : null; } catch (e) { return null; } };
const cfg = {};
const cfgNode = readNode('Get Gate Settings');
if (cfgNode) for (const it of cfgNode.all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; }
const usedDefaults = !cfg.speedtolead_eligible_stages;

const field = (id) => { const f = (contact.customFields || []).find((x) => x.id === id); return f ? String(f.value !== undefined ? f.value : (f.fieldValue ?? '')).trim().toLowerCase() : ''; };
let stage = field(cfg.stage_field_id || 'YOUR_GHL_FIELD_ID_STAGE');
if (!stage) {
  // contact from before the stage field existed: fall back to the legacy lead status, same rule as the inbound lookup
  const legacy = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS');
  const booked = String(cfg.legacy_booked_statuses || 'booked_emergency,booked_standard').split(',').map((s) => s.trim());
  stage = booked.includes(legacy) ? 'booked' : 'contact';
}
const eligible = String(cfg.speedtolead_eligible_stages || 'contact,lead').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const out = (decision, reason, extra = {}) => [{ json: { ...base, phone, stage, decision, reason, ...extra } }];

if (!eligible.includes(stage)) return out('denied_stage', `stage "${stage}" is not eligible for speed-to-lead (${eligible.join('/')})`);

const tag = String(cfg.human_contacted_tag || 'human-contacted').trim().toLowerCase();
if ((contact.tags || []).map((t) => String(t).trim().toLowerCase()).includes(tag)) return out('denied_human_reached', `contact carries the "${tag}" tag: a team member already reached this lead`);

if (!phone) return out('denied_no_phone', 'contact has no phone number to dial');

const lock = readNode('Check Active Call (Redis)');
const lockItem = lock ? lock.first().json : null;
if (!lockItem || lockItem.error) {
  return out('lock_check_failed', 'could not read the active-call lock', { alert: true, alert_text: `Contact Gate could not read the active-call lock for ${req.contact_id} (${lockItem && lockItem.error ? String(lockItem.error.message || lockItem.error).slice(0, 200) : 'node did not run'}). Denying ${req.channel} (fail-closed).` });
}
if (lockItem.lockValue !== undefined && lockItem.lockValue !== null && String(lockItem.lockValue) !== '') return out('denied_active_call', 'this number is on a call or already being called');

const tz = cfg.timezone || 'America/Phoenix';
const qStart = String(cfg.speedtolead_quiet_start || '21:00').trim();
const qEnd = String(cfg.speedtolead_quiet_end || '08:00').trim();
const now = DateTime.now().setZone(tz);
const hm = now.toFormat('HH:mm');
const inQuiet = qStart <= qEnd ? (hm >= qStart && hm < qEnd) : (hm >= qStart || hm < qEnd);
const exempt = ['call1', 'call2'].includes(req.attempt);
if (inQuiet && !exempt) {
  const [eh, em] = qEnd.split(':').map(Number);
  let until = now.set({ hour: eh, minute: em, second: 0, millisecond: 0 });
  if (until <= now) until = until.plus({ days: 1 });
  return out('deferred_quiet_hours', `${hm} ${tz} is inside quiet hours ${qStart}-${qEnd}; ${req.attempt} waits until ${qEnd}`, { deferred: true, delay_until: until.toISO() });
}

return out('allowed', `speed-to-lead ${req.attempt} allowed (stage ${stage}${inQuiet ? ', quiet-hours exempt' : ''}${usedDefaults ? ', built-in settings used' : ''})`, { allowed: true });
